import { FilterForm } from 'models';
import {
  BarClickParams,
  ViewByDisabledCondition,
  WaterfallConfig,
} from 'pages/pillars/ValueCreation/PerformanceTool/config/types';

import {
  getAppliedKeyForWaterfallFilter,
  hasSpecificValue,
  resolveCommercialWaterfallDrillValue,
} from '../utils/resolveCommercialResultsWaterfallOptions';

const BASE_WATERFALL_FILTER_DISABLED_CONDITIONS: ViewByDisabledCondition[] = [
  ({ activeSubFilters }) => activeSubFilters?.waterfall_filter === 'sku',
];

const applyWaterfallDrill = ({
  waterfallFilter,
  clickedLabel,
  dataFilters,
  applied,
  applyDirect,
}: Pick<BarClickParams, 'applyDirect' | 'dataFilters' | 'applied'> & {
  waterfallFilter: string;
  clickedLabel: string | string[];
}) => {
  const appliedKey = getAppliedKeyForWaterfallFilter(waterfallFilter);
  if (!appliedKey) {
    return;
  }

  applyDirect({
    [appliedKey]: resolveCommercialWaterfallDrillValue(
      waterfallFilter,
      clickedLabel,
      dataFilters,
      applied,
    ),
  });
};

export const createBaseWaterfallConfig = (
  kpiName: string,
): WaterfallConfig => ({
  kpiName,

  viewByToGrouping: {},

  groupingToViewBy: {},

  isViewByDisabled: (contextKey, activeSubFilters, applied) =>
    BASE_WATERFALL_FILTER_DISABLED_CONDITIONS.some((condition) =>
      condition({ contextKey, activeSubFilters, applied }),
    ),

  handleBarClick: ({
    index,
    labels,
    activeSubFilters,
    dataFilters,
    applied,
    applyDirect,
    syncWaterfallFilterAfterDrill,
  }: BarClickParams) => {
    const currentView = activeSubFilters?.waterfall_filter as string;

    const clickedLabel = labels?.[index];
    if (
      !clickedLabel &&
      (currentView !== 'sku' || !hasSpecificValue(applied.sku))
    )
      return;

    const handlers: Record<string, VoidFunction> = {
      region: () =>
        applyWaterfallDrill({
          waterfallFilter: 'region',
          clickedLabel,
          dataFilters,
          applied,
          applyDirect,
        }),
      brand: () =>
        applyWaterfallDrill({
          waterfallFilter: 'brand',
          clickedLabel,
          dataFilters,
          applied,
          applyDirect,
        }),
      channel: () =>
        applyWaterfallDrill({
          waterfallFilter: 'channel',
          clickedLabel,
          dataFilters,
          applied,
          applyDirect,
        }),
      pack_type: () =>
        applyWaterfallDrill({
          waterfallFilter: 'pack_type',
          clickedLabel,
          dataFilters,
          applied,
          applyDirect,
        }),
      sub_brand: () =>
        applyWaterfallDrill({
          waterfallFilter: 'sub_brand',
          clickedLabel,
          dataFilters,
          applied,
          applyDirect,
        }),
      sku: () => {
        const label = Array.isArray(clickedLabel)
          ? clickedLabel[0]
          : clickedLabel;
        applyDirect({
          sku: label
            ? resolveCommercialWaterfallDrillValue(
                'sku',
                label,
                dataFilters,
                applied,
              )
            : 'All',
        });
      },
    };

    handlers[currentView]?.();
    syncWaterfallFilterAfterDrill?.(currentView, clickedLabel);
  },

  getContextKey: (applied: FilterForm) => {
    if (!applied) {
      return 'global';
    }

    if (hasSpecificValue(applied.sub_brands)) {
      return 'sub_brand';
    }

    if (hasSpecificValue(applied.brands)) {
      return 'brand';
    }

    return 'global';
  },
});
